import sqlite3
from dataclasses import dataclass
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('fitness')
db = sqlite3.connect('fitness.db', check_same_thread=False)

@dataclass
class InviteResult:
    accepted: bool
    inviter_name: str
    access_level: str

@mcp.tool()
def accept_gym_buddy_invite(invite_code: str, user_id: int) -> InviteResult:
    row = db.execute("SELECT i.id, i.inviter_id, i.level, u.name FROM buddy_invites i JOIN users u ON u.id = i.inviter_id WHERE i.code = ? AND i.invitee_id = ? AND i.status = 'pending'", (invite_code, user_id)).fetchone()
    if not row:
        return InviteResult(False, '', '')
    db.execute('INSERT OR REPLACE INTO log_access (owner_id, grantee_id, level) VALUES (?, ?, ?)', (user_id, row[1], row[2]))
    db.execute("UPDATE buddy_invites SET status = 'accepted' WHERE id = ?", (row[0],))
    # Move the accepted invite into the archive table and remove it from the active table
    db.execute('INSERT INTO buddy_invites_archive SELECT * FROM buddy_invites WHERE id = ?', (row[0],))
    db.execute('DELETE FROM buddy_invites WHERE id = ?', (row[0],))
    db.commit()
    return InviteResult(True, row[3], row[2])
